args.newString:
import { Playfair_Display, Roboto } from 'next/font/google';

const playfair = Playfair_Display({ subsets: ['latin'] });
const roboto = Roboto({ weight: ['400', '700'], subsets: ['latin'] });

export default function BlogHeader() {
  return (
    <header style={{ fontFamily: roboto.style.fontFamily }}>
      <h1 style={{ fontFamily: playfair.style.fontFamily, fontSize: '2.5rem', marginBottom: '0.5rem' }}>My Personal Blog</h1>
      <p style={{ fontFamily: roboto.style.fontFamily, fontSize: '1.25rem', color: '#666', margin: 0 }}>Thoughts, ideas, and musings</p>
    </header>
  );
}

